def validate_stp_decode_events(events, ports, link_ids):
    """stp-decode 事件：原链路项与 t/port/data 原始帧按 t 非降混合。

    链路项沿用 forward-stp；帧子序列复用 forward-decode 全量校验
    （hex、最短长度、单层 8100、双标签拒绝、MAC 合法性），再在混合序上
    重放跨类型的 t 非降。
    """
    if not isinstance(events, list):
        raise InvalidInput("events must be a list")
    frame_docs = []
    frame_positions = set()
    for index, event in enumerate(events):
        if not isinstance(event, dict):
            raise InvalidInput("bad event")
        keys = frozenset(event)
        if keys == STP_DECODE_FRAME_KEYS:
            frame_docs.append(event)
            frame_positions.add(index)
        elif keys != STP_EVENT_KEYS:
            raise InvalidInput("bad event")
    # 帧子序列的外壳（hex、8100、双标签）与 MAC 规则同 forward-decode
    checked_frames = validate_forward_decode_frames(frame_docs, ports)
    raw_by_pos = dict(zip(sorted(frame_positions), checked_frames))
    result = []
    prev_t = None
    for index, event in enumerate(events):
        t = event["t"]
        if not _is_int(t) or t < 0:
            raise InvalidInput("bad t")
        if prev_t is not None and t < prev_t:  # 链路与帧混合序上 t 非降
            raise InvalidInput("t not monotonic")
        prev_t = t
        if index in raw_by_pos:
            _, port_name, raw = raw_by_pos[index]
            result.append(("frame", t, port_name, raw))
        else:
            lid = event["id"]
            up = event["up"]
            if not isinstance(lid, str) or not lid or lid not in link_ids:
                raise InvalidInput("bad event id")
            if not isinstance(up, bool):
                raise InvalidInput("bad up")
            result.append(("link", t, lid, up))
    return result


def stp_decode(
    bridges, links, delay, bridge_name, ports, age, max_frame, events,
    observer=None,
):
    # 原始帧按 frame-decode 规则解码为 stp-check 的九元组事件序
    # （alignment 恒真，分类退化为 runt/giant/bad_fcs/good），链路项原样
    # 保留；转发、学习与统计随后完全沿用 stp-check。observer 透传，由
    # stp-check 主体逐事件记录（record/replay）。
    raw_frames = [
        (item[1], item[2], item[3]) for item in events if item[0] == "frame"
    ]
    decoded_frames = _decode_raw_frames(raw_frames)
    decoded = []
    frame_index = 0
    for item in events:
        if item[0] == "link":
            decoded.append(item)
        else:
            t, port_name, src, dst, vlan, length, fcs, alignment = (
                decoded_frames[frame_index]
            )
            frame_index += 1
            decoded.append(
                ("frame", t, port_name, src, dst, vlan, length, fcs, alignment)
            )
    return forward_stp_check(
        bridges, links, delay, bridge_name, ports, age, max_frame, decoded,
        observer=observer,
    )


# igmp-snoop-decode：在 stp-decode（stp-check 七键）配置上追加 igmp 对象
IGMP_SNOOP_CONFIG_KEYS = STP_CHECK_CONFIG_KEYS | frozenset(("igmp",))
IGMP_KEYS = frozenset(("membership_age", "router_ports"))
IPV4_ETHER_TYPE = 0x0800
IP_PROTOCOL_IGMP = 2
IGMP_TYPE_QUERY_V2 = 0x11
IGMP_TYPE_REPORT_V2 = 0x16
IGMP_TYPE_LEAVE_V2 = 0x17
IGMP_TYPE_REPORT_V3 = 0x22
IGMP_CONTROL_ACTIONS = {
    IGMP_TYPE_QUERY_V2: "igmp_query",
    IGMP_TYPE_REPORT_V2: "igmp_report",
    IGMP_TYPE_LEAVE_V2: "igmp_leave",
}
# IGMPv3 Membership Report 组记录类型
IGMPV3_MODE_IS_INCLUDE = 1
IGMPV3_MODE_IS_EXCLUDE = 2
IGMPV3_CHANGE_TO_INCLUDE = 3
IGMPV3_CHANGE_TO_EXCLUDE = 4
IGMPV3_ALLOW_NEW_SOURCES = 5
IGMPV3_BLOCK_OLD_SOURCES = 6
IGMPV3_RECORD_TYPES = frozenset(range(1, 7))
IPV4_MC_MAC_PREFIX = b"\x01\x00\x5e"


def validate_igmp_snoop_config(config):
    if (
        not isinstance(config, dict)
        or frozenset(config) != IGMP_SNOOP_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    # 七键与 stp-decode（stp-check）完全一致，复用其全量校验
    bridges, links, delay, bridge, ports, age, max_frame = (
        validate_stp_check_config(
            {key: config[key] for key in STP_CHECK_CONFIG_KEYS}
        )
    )
    igmp = config["igmp"]
    if not isinstance(igmp, dict) or frozenset(igmp) != IGMP_KEYS:
        raise InvalidInput("bad igmp")
    membership_age = igmp["membership_age"]
    if not _is_int(membership_age) or membership_age <= 0:
        raise InvalidInput("bad igmp membership_age")
    router_ports = igmp["router_ports"]
    if not isinstance(router_ports, list):
        raise InvalidInput("bad igmp router_ports")
    name_set = {port["name"] for port in ports}
    for name in router_ports:
        if not isinstance(name, str) or name not in name_set:
            raise InvalidInput("bad igmp router port")
    if len(set(router_ports)) != len(router_ports):  # 端口名不重复
        raise InvalidInput("bad igmp router_ports")
    return (
        bridges, links, delay, bridge, ports, age, max_frame,
        membership_age, tuple(router_ports),
    )


def _internet_checksum(data):
    """IPv4/IGMP 反码求和校验；奇数尾字节补零，校验时整段求和须为 0。"""
    if len(data) % 2:
        data = data + b"\x00"
    total = 0
    for index in range(0, len(data), 2):
        total += (data[index] << 8) | data[index + 1]
    while total >> 16:
        total = (total & 0xFFFF) + (total >> 16)
    return (~total) & 0xFFFF


def _parse_igmp_outer(raw, ethertype_offset):
    """解析 IPv4 帧外层并定位未分片的 IGMP 报文。

    - 返回 None：非 IPv4/IGMP、IPv4 头非法或校验失败、任何分片，调用方按
      普通 IPv4 帧处理（组播沿用泛洪或成员投递）；
    - 返回 ("invalid",)：IPv4 外层合法且为未分片协议号 2，但 IPv4 总长度
      容纳不了最短 IGMP 报文或超过实际载荷，调用方固定输出 igmp_invalid；
    - 返回 ("ok", igmp_msg)：校验通过的外层，igmp_msg 为按 IPv4 总长度截
      取的完整 IGMP 报文（调用方按类型继续校验）。
    """
    payload = raw[ethertype_offset + 2:-4]
    if len(payload) < 20:
        return None
    version_ihl = payload[0]
    if version_ihl >> 4 != 4:
        return None
    ihl = version_ihl & 0x0F
    if ihl < 5:
        return None
    header_len = ihl * 4
    if len(payload) < header_len:
        return None
    if _internet_checksum(payload[:header_len]) != 0:  # IPv4 头校验
        return None
    fragment_word = (payload[6] << 8) | payload[7]
    # MF（bit13）或片偏移（bit0..12）非零：任何分片都不识别；DF 忽略
    if fragment_word & 0x3FFF:
        return None
    if payload[9] != IP_PROTOCOL_IGMP:
        return None
    total_length = (payload[2] << 8) | payload[3]
    # IGMPv2 报文最短 8 字节；容纳不了或超过实际载荷均为非法
    if total_length < header_len + 8 or total_length > len(payload):
        return ("invalid",)
    return ("ok", payload[header_len:total_length])


def _igmp_v2_from_msg(igmp_msg):
    """对已截取的 IGMP 报文做 IGMPv2 Query/Report/Leave 校验。"""
    mtype = igmp_msg[0]
    if mtype not in IGMP_CONTROL_ACTIONS:
        return ("invalid",)  # 类型非法（含 IGMPv3 等）
    if len(igmp_msg) != 8:
        return ("invalid",)  # IGMPv2 Query/Report/Leave 恰为 8 字节
    if _internet_checksum(igmp_msg) != 0:  # IGMP 校验
        return ("invalid",)
    octets = igmp_msg[4:8]
    group = ".".join(str(value) for value in octets)
    if mtype in (IGMP_TYPE_REPORT_V2, IGMP_TYPE_LEAVE_V2):
        if not 224 <= octets[0] <= 239:  # Report/Leave 组地址须为 D 类
            return ("invalid",)
    else:
        # Query：通用查询组地址 0.0.0.0 合法，组特定查询须为 D 类，
        # 其余组地址非法
        if tuple(octets) != (0, 0, 0, 0) and not 224 <= octets[0] <= 239:
            return ("invalid",)
    return ("ok", mtype, group)


def _ipv4_unicast(octets):
    """有效单播地址：首字节 1..223（A/B/C 类），排除 127 环回段；
    0.x 为本网、224+ 为组播/保留/广播。"""
    return 1 <= octets[0] <= 223 and octets[0] != 127


def _parse_igmp_v3_report(igmp_msg):
    """校验并解析 IGMPv3 Membership Report（类型 0x22）。

    返回 ("invalid",) 或 ("v3", records)；records 为
    (rtype, group, [source, ...]) 列表，group/source 为点分十进制。
    校验：整报校验和为 0、恰 8 字节定长头、组记录数与内容一致且长度闭合、
    记录类型在 1 至 6、组地址为 D 类、源地址为有效单播。
    """
    if len(igmp_msg) < 8 or igmp_msg[0] != IGMP_TYPE_REPORT_V3:
        return ("invalid",)
    if _internet_checksum(igmp_msg) != 0:  # IGMP 校验
        return ("invalid",)
    record_count = (igmp_msg[6] << 8) | igmp_msg[7]
    offset = 8
    records = []
    for _ in range(record_count):
        if len(igmp_msg) - offset < 8:  # 记录定长头 8 字节
            return ("invalid",)
        rtype = igmp_msg[offset]
        aux_len = igmp_msg[offset + 1]
        source_count = (
            (igmp_msg[offset + 2] << 8) | igmp_msg[offset + 3]
        )
        group_octets = igmp_msg[offset + 4:offset + 8]
        if rtype not in IGMPV3_RECORD_TYPES:
            return ("invalid",)
        if not 224 <= group_octets[0] <= 239:  # 组地址须为 D 类
            return ("invalid",)
        body_end = offset + 8 + 4 * source_count
        record_end = body_end + 4 * aux_len
        if record_end > len(igmp_msg):  # 源数组或辅助数据长度不闭合
            return ("invalid",)
        sources = []
        for source_index in range(source_count):
            start = offset + 8 + 4 * source_index
            source_octets = igmp_msg[start:start + 4]
            if not _ipv4_unicast(source_octets):  # 源地址须为有效单播
                return ("invalid",)
            sources.append(
                ".".join(str(value) for value in source_octets)
            )
        records.append(
            (
                rtype,
                ".".join(str(value) for value in group_octets),
                sources,
            )
        )
        offset = record_end
    if offset != len(igmp_msg):  # 记录数与内容不符（有剩余字节）
        return ("invalid",)
    return ("v3", records)


def _parse_igmp(raw, ethertype_offset):
    """IGMP 统一解析：在外层校验基础上区分 IGMPv2 三类与 IGMPv3 Report。

    返回 None（不识别为 IGMP）、("invalid",)（外层合法但 IGMP 非法）、
    ("ok", mtype, group)（IGMPv2）或 ("v3", records)（IGMPv3 Report）。
    """
    outer = _parse_igmp_outer(raw, ethertype_offset)
    if outer is None:
        return None
    if outer[0] == "invalid":
        return ("invalid",)
    igmp_msg = outer[1]
    if igmp_msg[0] == IGMP_TYPE_REPORT_V3:
        return _parse_igmp_v3_report(igmp_msg)
    return _igmp_v2_from_msg(igmp_msg)


def _ipv4_multicast_data(raw, ethertype_offset):
    """IPv4 组播数据帧：目的组地址为 D 类且与目的 MAC 映射一致时返回
    (source, group) 点分十进制（source 原样读取，是否投递交成员过滤条件
    判定），否则返回 None（调用方沿用泛洪）。"""
    payload = raw[ethertype_offset + 2:-4]
    if len(payload) < 20:
        return None
    source_octets = payload[12:16]
    group_octets = payload[16:20]
    if not 224 <= group_octets[0] <= 239:
        return None
    expected_mac = IPV4_MC_MAC_PREFIX + bytes(
        (group_octets[1] & 0x7F, group_octets[2], group_octets[3])
    )
    if raw[0:6] != expected_mac:
        return None
    return (
        ".".join(str(value) for value in source_octets),
        ".".join(str(value) for value in group_octets),
    )


def _forward_stp_work_total(bridges, links, ports, events):
    """forward-stp 工作量公式总值（不含上限比较），供 forward-stp 系与
    igmp-snoop-decode 复用。B、L、P 为桥、链路、端口数，U 为 up 链路数，
    E 为此前帧数：初始收敛 B+L+2U；帧计 E+P+1；链路计
    E*(P+1)+B+L+2U+2P+1（幂等也计，U 先应用）。
    """
    B = len(bridges)
    L = len(links)
    P = len(ports)
    sim_up = {link["id"]: link["up"] for link in links}
    U = sum(1 for link in links if link["up"])
    E = 0
    work = B + L + 2 * U  # 初始收敛
    for item in events:
        if item[0] == "link":
            _, _, lid, up = item
            if sim_up[lid] != up:
                sim_up[lid] = up
                U += 1 if up else -1
            work += E * (P + 1) + B + L + 2 * U + 2 * P + 1
        else:
            work += E + P + 1
            E += 1
    return work


def forward_stp_work(bridges, links, ports, events, limit):
    """forward-stp 的工作量预演：仅跟踪 up 链路数与帧数，无副作用。

    累计等于上限合法，首次超过即抛 ForwardStpWorkLimit。
    """
    if _forward_stp_work_total(bridges, links, ports, events) > limit:
        raise ForwardStpWorkLimit


def _igmp_v3_work_units(events):
    """统计帧序列中合法 IGMPv3 Report 的组记录数与源地址数之和。

    仅依据原始帧外层与报文解析（与帧分类、VLAN 准入、STP 状态无关，预演
    无副作用）：每个完整解析成功的 v3 组记录计 1，其每个源地址再计 1。
    """
    units = 0
    for item in events:
        if item[0] != "frame":
            continue
        raw = item[3]
        ethertype_offset = 16 if raw[12:14] == FRAME_DECODE_TAG else 12
        ethertype = (
            (raw[ethertype_offset] << 8) | raw[ethertype_offset + 1]
        )
        if ethertype != IPV4_ETHER_TYPE:
            continue
        igmp_info = _parse_igmp(raw, ethertype_offset)
        if igmp_info is not None and igmp_info[0] == "v3":
            records = igmp_info[1]
            units += len(records) + sum(
                len(sources) for _, _, sources in records
            )
    return units


def igmp_snoop_work(bridges, links, ports, events, limit):
    """igmp-snoop-decode 工作量预演：现有 stp-decode（forward-stp）工作量
    再加 N*(N+P+1)，N 为事件数（链路与帧合计）、P 为端口数；IGMPv3
    Report 每个组记录及每个源地址各再加一个单位。等于上限合法，超过即
    抛 IgmpWorkLimit。
    """
    N = len(events)
    P = len(ports)
    work = _forward_stp_work_total(bridges, links, ports, events)
    work += N * (N + P + 1)
    work += _igmp_v3_work_units(events)
    if work > limit:
        raise IgmpWorkLimit


def igmp_snoop_decode(
    bridges, links, delay, bridge_name, ports, age, max_frame,
    membership_age, router_ports, events, observer=None,
):
    """在 stp-decode 转发/学习/统计语义上增加 IGMPv2/v3 snooping。

    成员表 membership：(vlan, group) -> {port: member}。IGMPv2 成员为
    expires（绝对时刻）整数，键形保持 name/expires；经 IGMPv3 Report 更新
    的成员为 {"expires": expires, "mode": "include"/"exclude",
    "sources": set(点分十进制源地址)}。
    每个事件前删除 expires<=t 的成员；IGMPv2 Report 建立或刷新至
    t+membership_age，Leave 立即删除入端口成员；IGMPv3 Report 按组记录
    顺序在暂存表上修改过滤状态，整帧校验成功后一次提交，受影响成员
    expires 统一为 t+membership_age；链路断开或端口退出 forwarding 时清除
    该端口全部成员。Report/Leave 仅发往同 VLAN 可转发的 router_ports，无
    合格路由端口时泛洪；Query 始终泛洪；其他 IPv4 组播在 MAC/组地址映射
    一致且有成员匹配源过滤条件时仅发往匹配成员与路由端口；其余组播沿用
    泛洪。协议号 2 但 IGMP 非法的帧固定 igmp_invalid、空 ports、计 drop
    且不改任何状态。observer 语义同 stp-check。
    """
    by_id = {link["id"]: link for link in links}
    by_name = {port["name"]: port for port in ports}
    port_link = {}  # 本桥桥链路口名 -> link
    for link in links:
        for end_bridge, end_port in (link["x"], link["y"]):
            if end_bridge == bridge_name:
                port_link[end_port] = link
    fdb = {}  # (vlan, mac) -> [port, seen]
    # (vlan, group) -> {port_name: int 过期时刻或 v3 过滤 dict}
    membership = {}
    router_set = set(router_ports)
    port_stats = {
        port["name"]: {
            "rx": 0,
            "tx": 0,
            "drop": 0,
            "good": 0,
            "runt": 0,
            "giant": 0,
            "alignment": 0,
            "bad_fcs": 0,
        }
        for port in ports
    }
    vlan_stats = {}
    for port in ports:
        for vlan in port["allowed"]:
            vlan_stats.setdefault(vlan, {"rx": 0, "tx": 0, "drop": 0})
    results = []
    if observer is not None:  # record/replay：逐事件记录 applied 与输出
        observer["items"] = []

    previous = {}  # (bridge, port) -> 上一轮角色
    since = {}  # (bridge, port) -> 获得当前 root/designated 角色的时刻
    roles = {name: {} for name in bridges}

    def converge(t):
        _, _, new_roles = stp_converge(bridges, links)
        for name in bridges:
            for port, role in new_roles[name].items():
                key = (name, port)
                if role in STP_TIMED_ROLES:
                    if previous.get(key) != role:  # 同角色不重计时
                        since[key] = t
                else:
                    since.pop(key, None)
        previous.clear()
        for name in bridges:
            for port, role in new_roles[name].items():
                previous[(name, port)] = role
        roles.clear()
        for name in bridges:
            roles[name] = new_roles[name]

    def forwarding_ports(t):
        result = set()
        for name, link in port_link.items():
            key = (bridge_name, name)
            role = roles[bridge_name][name]
            if (
                by_name[name]["up"]
                and link["up"]
                and role in STP_TIMED_ROLES
                and t - since[key] >= 2 * delay
            ):
                result.add(name)
        return result

    def port_status(name, t):
        """返回 (物理 up, STP 状态)；边缘口恒为 up 即 forwarding。"""
        port = by_name[name]
        link = port_link.get(name)
        if link is None:
            return port["up"], ("forwarding" if port["up"] else "down")
        if not port["up"]:
            return False, "down"
        if not link["up"]:
            return False, "disabled"
        role = roles[bridge_name][name]
        if role in STP_TIMED_ROLES:
            elapsed = t - since[(bridge_name, name)]
            if elapsed < delay:
                state = "discarding"
            elif elapsed < 2 * delay:
                state = "learning"
            else:
                state = "forwarding"
        else:
            state = "discarding"  # alternate
        return True, state

    def eligible_names(t, vlan, ingress):
        """同 VLAN 可转发（物理 up、STP forwarding、VLAN 准入）且排除入
        端口的端口名，按配置端口序。"""
        return [
            port["name"]
            for port in ports
            if vlan in port["allowed"]
            and port["name"] != ingress
            and port_status(port["name"], t) == (True, "forwarding")
        ]

    def member_expires(entry):
        """v2 成员为过期时刻整数；v3 成员为含 expires 的过滤 dict。"""
        return entry if isinstance(entry, int) else entry["expires"]

    def apply_v3_record(table, port_name, rtype, sources, expiry):
        """按单条 v3 组记录修改入端口在本组的暂存过滤状态。

        无记录或 v2 成员按 EXCLUDE、空源集合处理；INCLUDE 空集合删除
        成员，EXCLUDE 空集合表示接收全部源。
        """
        sources = set(sources)
        current = table.get(port_name)
        if isinstance(current, dict):
            mode, current_sources = current["mode"], set(current["sources"])
        elif isinstance(current, int):
            # IGMPv2 成员接收全部源，按 EXCLUDE、空集合处理
            mode, current_sources = "exclude", set()
        else:
            # 无既有成员等价于 INCLUDE、空集合：ALLOW 建立成员，
            # BLOCK 仍为空集合删除
            mode, current_sources = "include", set()
        if rtype in (IGMPV3_MODE_IS_INCLUDE, IGMPV3_CHANGE_TO_INCLUDE):
            new_mode, new_sources = "include", sources
        elif rtype in (IGMPV3_MODE_IS_EXCLUDE, IGMPV3_CHANGE_TO_EXCLUDE):
            new_mode, new_sources = "exclude", sources
        elif rtype == IGMPV3_ALLOW_NEW_SOURCES:
            if mode == "include":  # INCLUDE 取并集
                new_mode, new_sources = "include", current_sources | sources
            else:  # EXCLUDE 做差集
                new_mode, new_sources = "exclude", current_sources - sources
        else:  # BLOCK_OLD_SOURCES：INCLUDE 做差集，EXCLUDE 取并集
            if mode == "include":
                new_mode, new_sources = "include", current_sources - sources
            else:
                new_mode, new_sources = "exclude", current_sources | sources
        if new_mode == "include" and not new_sources:
            table.pop(port_name, None)  # INCLUDE 空集合：删除成员
        else:
            table[port_name] = {
                "expires": expiry,
                "mode": new_mode,
                "sources": new_sources,
            }

    def member_matches(entry, source):
        """组播数据源过滤：v2 成员接收全部源；v3 成员按 INCLUDE/EXCLUDE。"""
        if not isinstance(entry, dict):
            return True
        if entry["mode"] == "include":
            return source in entry["sources"]
        return source not in entry["sources"]

    def purge_expired(t):
        for key, table in [
            (key, table) for key, table in membership.items()
        ]:
            for port_name in [
                name
                for name, entry in table.items()
                if member_expires(entry) <= t
            ]:
                del table[port_name]
            if not table:
                del membership[key]

    converge(0)
    for item in events:
        t = item[1]
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        purge_expired(t)  # 每个事件前删除 expires<=t 的成员
        if item[0] == "link":
            _, t, lid, up = item
            applied = by_id[lid]["up"] != up  # up 实际改变才 applied
            old_forwarding = forwarding_ports(t)
            by_id[lid]["up"] = up
            converge(t)
            left_forwarding = old_forwarding - forwarding_ports(t)
            for name in left_forwarding:
                # 端口退出 forwarding：清 FDB（同 stp-decode）与该端口全部
                # 组成员（链路断开同理，断口必退出 forwarding）
                for key in [k for k, (p, _) in fdb.items() if p == name]:
                    del fdb[key]
                for key, table in [
                    (key, table) for key, table in membership.items()
                ]:
                    if name in table:
                        del table[name]
                        if not table:
                            del membership[key]
            if observer is not None:  # 链路项：output 恒 None
                observer["items"].append(
                    {"kind": "link", "t": t, "applied": applied,
                     "output": None}
                )
            continue
        _, t, port_name, raw = item
        dst = _format_mac(raw[0:6])
        src = _format_mac(raw[6:12])
        if raw[12:14] == FRAME_DECODE_TAG:
            tci = (raw[14] << 8) | raw[15]
            tag = tci & 0x0FFF
            ethertype_offset = 16
        else:
            tag = None
            ethertype_offset = 12
        ethertype = (
            (raw[ethertype_offset] << 8) | raw[ethertype_offset + 1]
        )
        length = len(raw)
        port_stats[port_name]["rx"] += 1
        if length < FRAME_CHECK_RUNT_LENGTH:
            cls = "runt"
        elif length > max_frame:
            cls = "giant"
        elif raw[-4:] != (
            zlib.crc32(raw[:-4]) & 0xFFFFFFFF
        ).to_bytes(4, "little"):
            cls = "bad_fcs"
        else:
            cls = "good"
        port_stats[port_name][cls] += 1
        if cls != "good":  # 非 good 丢弃且不学习、不转发、不计 VLAN
            port_stats[port_name]["drop"] += 1
            entry = {"t": t, "class": cls, "action": "drop", "ports": []}
            results.append(entry)
            if observer is not None:
                observer["items"].append(
                    {"kind": "frame", "t": t, "applied": True,
                     "output": entry}
                )
            continue
        if tag is None:
            vlan = by_name[port_name]["pvid"]
            rejected = False
        else:
            vlan = tag
            ingress = by_name[port_name]
            rejected = (
                ingress["mode"] == "access" or vlan not in ingress["allowed"]
            )
        if rejected:  # VLAN 准入拒绝：不学习、不计 VLAN
            port_stats[port_name]["drop"] += 1
            entry = {"t": t, "class": cls, "action": "drop", "ports": []}
            results.append(entry)
            if observer is not None:  # 准入拒绝也逐帧记录
                observer["items"].append(
                    {"kind": "frame", "t": t, "applied": True,
                     "output": entry}
                )
            continue
        vlan_stats[vlan]["rx"] += 1
        _, state = port_status(port_name, t)
        egress = []
        action = "drop"
        if state == "learning":
            fdb[(vlan, src)] = [port_name, t]
        elif state == "forwarding":
            igmp_info = (
                _parse_igmp(raw, ethertype_offset)
                if ethertype == IPV4_ETHER_TYPE
                else None
            )
            if igmp_info is not None and igmp_info[0] == "invalid":
                # 外层合法的协议号 2 帧但 IGMP 非法：不改任何状态，
                # action 固定 igmp_invalid、ports 为空并计入丢弃
                port_stats[port_name]["drop"] += 1
                vlan_stats[vlan]["drop"] += 1
                entry = {
                    "t": t, "class": cls, "action": "igmp_invalid",
                    "ports": [],
                }
                results.append(entry)
                if observer is not None:
                    observer["items"].append(
                        {"kind": "frame", "t": t, "applied": True,
                         "output": entry}
                    )
                continue
            fdb[(vlan, src)] = [port_name, t]
            is_group = int(dst[:2], 16) & 1
            eligible = eligible_names(t, vlan, port_name)
            if igmp_info is not None and igmp_info[0] == "v3":
                # IGMPv3 Membership Report：解析已对整帧校验成功，此处一次
                # 提交；组记录按报文顺序作用，受影响成员 expires 统一为
                # t+membership_age
                _, records = igmp_info
                expiry = t + membership_age
                for rtype, group, sources in records:
                    table = membership.setdefault((vlan, group), {})
                    apply_v3_record(
                        table, port_name, rtype, sources, expiry
                    )
                    if not table:
                        del membership[(vlan, group)]
                routers = [
                    name for name in eligible if name in router_set

                    name for name in eligible if name in router_set
                ]
                egress = routers if routers else eligible
                action = "igmpv3_report"
            elif igmp_info is not None:  # 合法 IGMPv2 控制帧
                _, mtype, group = igmp_info
                if mtype == IGMP_TYPE_REPORT_V2:
                    membership.setdefault((vlan, group), {})[port_name] = (
                        t + membership_age
                    )
                    routers = [
                        name for name in eligible if name in router_set
                    ]
                    egress = routers if routers else eligible
                    action = "igmp_report"
                elif mtype == IGMP_TYPE_LEAVE_V2:
                    table = membership.get((vlan, group))
                    if table is not None:  # Leave 立即删除入端口成员
                        table.pop(port_name, None)
                        if not table:
                            del membership[(vlan, group)]
                    routers = [
                        name for name in eligible if name in router_set
                    ]
                    egress = routers if routers else eligible
                    action = "igmp_leave"
                else:  # Query：始终泛洪，不改成员状态
                    egress = eligible
                    action = "igmp_query"
            elif is_group:
                multicast = (
                    _ipv4_multicast_data(raw, ethertype_offset)
                    if ethertype == IPV4_ETHER_TYPE
                    else None
                )
                group = multicast[1] if multicast is not None else None
                table = (
                    membership.get((vlan, group))
                    if group is not None
                    else None
                )
                if table:  # 命中成员表：匹配源过滤的成员加路由端口
                    source = multicast[0]
                    matching = {
                        name
                        for name, entry in table.items()
                        if member_matches(entry, source)
                    }
                    targets = matching | router_set
                    egress = [
                        name for name in eligible if name in targets
                    ]
                    action = "multicast"
                else:  # 其余组播（含广播、非 IPv4、映射不一致、无成员）泛洪
                    egress = eligible
                    action = "flood"
            else:
                hit = fdb.get((vlan, dst))
                if hit is not None and hit[0] != port_name:
                    target = hit[0]
                    target_up, target_state = port_status(target, t)
                    if (
                        target_up
                        and target_state == "forwarding"
                        and vlan in by_name[target]["allowed"]
                    ):
                        egress = [target]
                        action = "unicast"
                elif hit is None:
                    egress = eligible
                    action = "flood"
        out_ports = []
        for name in egress:
            port_stats[name]["tx"] += 1
            vlan_stats[vlan]["tx"] += 1
            out_ports.append(
                {
                    "name": name,
                    "vlan": None if vlan in by_name[name]["untagged"] else vlan,
                }
            )
        if not egress:
            port_stats[port_name]["drop"] += 1
            vlan_stats[vlan]["drop"] += 1
        entry = {"t": t, "class": cls, "action": action, "ports": out_ports}
        results.append(entry)
        if observer is not None:  # 帧项恒 applied，output 为对应结果项
            observer["items"].append(
                {"kind": "frame", "t": t, "applied": True, "output": entry}
            )
    port_order = {port["name"]: index for index, port in enumerate(ports)}
    groups = []
    for vlan, group in sorted(
        membership,
        key=lambda key: (
            key[0], tuple(int(part) for part in key[1].split("."))
        ),
    ):
        table = membership[(vlan, group)]
        members = []
        # 成员按配置端口序；v2 成员保持 name/expires 键形，v3 成员按固定
        # 键序 name/expires/mode/sources，源地址数值升序
        for name in sorted(table, key=lambda value: port_order[value]):
            entry = table[name]
            if isinstance(entry, dict):
                sources = sorted(
                    entry["sources"],
                    key=lambda value: tuple(
                        int(part) for part in value.split(".")
                    ),
                )
                members.append(
                    {
                        "name": name,
                        "expires": entry["expires"],
                        "mode": entry["mode"],
                        "sources": sources,
                    }
                )
            else:
                members.append({"name": name, "expires": entry})
        groups.append({"vlan": vlan, "group": group, "members": members})
    return {
        "results": results,
        "ports": [
            {
                "name": port["name"],
                "rx": port_stats[port["name"]]["rx"],
                "tx": port_stats[port["name"]]["tx"],
                "drop": port_stats[port["name"]]["drop"],
                "good": port_stats[port["name"]]["good"],
                "runt": port_stats[port["name"]]["runt"],
                "giant": port_stats[port["name"]]["giant"],
                "alignment": port_stats[port["name"]]["alignment"],
                "bad_fcs": port_stats[port["name"]]["bad_fcs"],
            }
            for port in ports
        ],
        "vlans": [
            {
                "vlan": vlan,
                "rx": vlan_stats[vlan]["rx"],
                "tx": vlan_stats[vlan]["tx"],
                "drop": vlan_stats[vlan]["drop"],
            }
            for vlan in sorted(vlan_stats)
        ],
        "groups": groups,
    }


STORM_CHECK_CONFIG_KEYS = frozenset(
    ("bridges", "links", "delay", "bridge", "ports", "age", "storm",
     "max_frame")
)


QOS_DECODE_FRAME_KEYS = FRAME_DECODE_FRAME_KEYS  # {"t", "port", "data"}


def validate_qos_decode_events(events, ports, link_ids, lags):
    """qos-decode 事件：链路/成员/service 项与 t/port/data 原始帧按 t 非降混合。

    非帧项沿用 qos-check；帧子序列复用 forward-decode 全量校验（hex、
    最短长度、单层 8100、双标签拒绝、目的非全零、源非零单播），再在混合
    序上重放跨类型的 t 非降。
    """
    if not isinstance(events, list):
        raise InvalidInput("events must be a list")
    names = {port["name"] for port in ports}
    member_set = {member for lag in lags for member in lag["members"]}
    frame_docs = []
    frame_positions = set()
    for index, event in enumerate(events):
        if not isinstance(event, dict):
            raise InvalidInput("bad event")
        keys = frozenset(event)
        if keys == QOS_DECODE_FRAME_KEYS:
            frame_docs.append(event)
            frame_positions.add(index)
        elif keys not in (
            STP_EVENT_KEYS, MEMBER_EVENT_KEYS, SERVICE_EVENT_KEYS
        ):
            raise InvalidInput("bad event")
    # 帧子序列的外壳（hex、8100、双标签）与 MAC 规则同 forward-decode
    checked_frames = validate_forward_decode_frames(frame_docs, ports)
    raw_by_pos = dict(zip(sorted(frame_positions), checked_frames))
    result = []
    prev_t = None
    for index, event in enumerate(events):
        t = event["t"]
        if not _is_int(t) or t < 0:
            raise InvalidInput("bad t")
        if prev_t is not None and t < prev_t:  # 各类型混合序上 t 非降
            raise InvalidInput("t not monotonic")
        prev_t = t
        if index in raw_by_pos:
            _, port_name, raw = raw_by_pos[index]
            result.append(("frame", t, port_name, raw))
            continue
        keys = frozenset(event)
        if keys == STP_EVENT_KEYS:
            lid = event["id"]
            up = event["up"]
            if not isinstance(lid, str) or not lid or lid not in link_ids:
                raise InvalidInput("bad event id")
            if not isinstance(up, bool):
                raise InvalidInput("bad up")
            result.append(("link", t, lid, up))
        elif keys == MEMBER_EVENT_KEYS:
            member = event["member"]
            up = event["up"]
            if not isinstance(member, str) or member not in member_set:
                raise InvalidInput("bad event member")
            if not isinstance(up, bool):
                raise InvalidInput("bad up")
            result.append(("member", t, member, up))
        else:
            port = event["port"]
            count = event["count"]
            if not isinstance(port, str) or port not in names:
                raise InvalidInput("unknown port")
            if not _is_int(count) or count <= 0:
                raise InvalidInput("bad count")
            result.append(("service", t, port, count))
    return result


def _decode_qos_raw_frames(frames):
    """按 frame-decode 规则解析原始帧为 qos-check 的十元组帧序。

    无对齐概念，alignment 恒真；未标记帧 priority 恒为 0、vlan 为 None，
    分类退化为 runt/giant/bad_fcs/good。
    """
    checked = []
    for t, port, raw in frames:
        dst = _format_mac(raw[0:6])
        src = _format_mac(raw[6:12])
        if raw[12:14] == FRAME_DECODE_TAG:
            tci = (raw[14] << 8) | raw[15]
            priority = tci >> 13
            vlan = tci & 0x0FFF
            ethertype_offset = 16
        else:
            priority = 0
            vlan = None
            ethertype_offset = 12
        ethertype = (
            (raw[ethertype_offset] << 8) | raw[ethertype_offset + 1]
        )
        fcs = raw[-4:] == (zlib.crc32(raw[:-4]) & 0xFFFFFFFF).to_bytes(
            4, "little"
        )
        checked.append(
            (
                t, port, src, dst, vlan, ethertype, priority,
                len(raw), fcs, True,
            )
        )
    return checked


def _decode_qos_events(events):
    """把校验后的 qos-decode 混合事件转为 qos-check 十一元组事件序。

    链路/成员/service 项原样保留，原始帧按 frame-decode 规则解码
    （alignment 恒真，未标记 priority 恒 0、vlan 为 None）；工作量预演与
    正式仿真共用同一转换，保证计费与执行同形。
    """
    raw_frames = [
        (item[1], item[2], item[3]) for item in events if item[0] == "frame"
    ]
    decoded_frames = _decode_qos_raw_frames(raw_frames)
    decoded = []
    frame_index = 0
    for item in events:
        if item[0] == "frame":
            t, port_name = item[1], item[2]
            (
                _, _, src, dst, vlan, ethertype, priority,
                length, fcs, alignment,
            ) = decoded_frames[frame_index]
            frame_index += 1
            decoded.append(
                ("frame", t, port_name, src, dst, vlan, ethertype, priority,
                 length, fcs, alignment)
            )
        else:
            decoded.append(item)
    return decoded


def qos_decode(
    bridges, links, delay, bridge_name, ports, age, storm, lags, mirror,
    acl, qos, max_frame, events, observer=None, state_out=None,
):
    # 原始帧按 frame-decode 规则解码为 qos-check 的十一元组事件序
    # （alignment 恒真，分类退化为 runt/giant/bad_fcs/good），链路、成员、
    # service 项原样保留；统计、转发、学习、镜像与队列随后完全沿用
    # qos-check。observer/state_out 透传，由 qos-check 主体逐事件记录。
    decoded = _decode_qos_events(events)
    return forward_qos_check(
        bridges, links, delay, bridge_name, ports, age, storm, lags, mirror,
        acl, qos, max_frame, decoded, observer=observer, state_out=state_out,
    )


def validate_storm_check_config(config):
    if (
        not isinstance(config, dict)
        or frozenset(config) != STORM_CHECK_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    # bridges/links/delay/bridge/ports/age/storm 与 forward-stp-storm 契约
    # 一致，复用其全量校验
    bridges, links, delay, bridge, ports, age, storm = (
        validate_forward_stp_storm_config(
            {key: config[key] for key in STORM_CONFIG_KEYS}
        )
    )
    max_frame = config["max_frame"]
    if (
        not _is_int(max_frame)
        or not FRAME_CHECK_MIN_MAX_FRAME
        <= max_frame
        <= FRAME_CHECK_MAX_MAX_FRAME
    ):
        raise InvalidInput("bad max_frame")
    return bridges, links, delay, bridge, ports, age, storm, max_frame

stp-check/stp-decode（共享七键配置，按事件帧形状区分）、
forward-stp-storm、lag、mirror、acl、acl-check、qos、qos-check/
qos-decode（共享十二键配置，按事件帧形状区分）、security-check、
mirror-check、lag-check、storm-check、port-security，或 link-wire/
link-wire-decode（共享含 queue_bytes 配置，按事件帧形状区分），或
link-flow-decode（含 queue_bytes 与 flow_control 的端口配置，事件为
原始帧形状），或 qos-wire-decode/qos-pfc-decode（共享含 queue_bytes、
flow_control 与 qos 的配置，按每口是否均含 pfc 区分，混合即非法）。

events 非 None 时用于区分共享配置形状的两种模式：三键配置的非空帧
数组含 src（八键）按 forward-check，含 data（t/port/data 原始帧）按
forward-decode；两种帧形状混用报 InvalidInput；空数组沿用既有
forward-decode 路由（既有日志字节不变）。stp 七键配置的非链路帧含
src（九键）按 stp-check，含 data（t/port/data 原始帧）按 stp-decode；
两种帧形状混用报 InvalidInput；仅链路项或空事件沿用既有 stp-decode
路由（既有日志字节不变）。stp 七键加 igmp 的配置按 igmp-snoop-decode
（事件仅链路项与 t/port/data 原始帧）。qos 十二键配置的帧项含 src（十键）按
qos-check，含 data（t/port/data 原始帧）按 qos-decode，两种帧形状
混用报 InvalidInput；仅链路/成员/service 项或空事件沿用既有
qos-check 路由（既有日志字节不变）。link-wire 含 queue_bytes 配置的
帧项含 src（九键）按 link-wire，含 data（t/port/data 原始帧）按
link-wire-decode，两种帧形状混用报 InvalidInput；仅 link/advance 项
或空事件沿用既有 link-wire 路由（既有日志字节与旧哈希不变）。
"""
if isinstance(config, dict):
    keys = frozenset(config)
    # 恰含 ports,age 且 ports 为字符串数组时为 fdb 模式（forward 旧
    # 入口的 ports 为对象数组，形状不重叠）
    if keys == CONFIG_KEYS and isinstance(
        config.get("ports"), list
    ) and all(isinstance(p, str) for p in config["ports"]):
        return "fdb"
    # 恰含 ports,age 且 ports 为非空对象数组时为 forward 模式，旧式
    # access（name/vlan/up）与新式 802.1Q（name/mode/pvid/allowed/
    # untagged/up）两种端口形状均沿用 forward 入口识别与校验
    if (
        keys == CONFIG_KEYS
        and isinstance(config.get("ports"), list)
        and bool(config["ports"])
        and all(isinstance(p, dict) for p in config["ports"])
    ):
        return "forward"
    if keys == STP_CONFIG_KEYS:
        return "stp"
    if keys == LOOP_CONFIG_KEYS:
        return "loop"
    if keys == LINK_FORWARD_CONFIG_KEYS:
        # link-wire 与 link-forward 顶层同键，但端口形状不重叠：
        # link-wire 每口恰多 queue_bytes（八键），link-flow-decode 再
        # 多 flow_control（九键）。端口文档均含 flow_control 即按
        # link-flow-decode 路由（必同时含 queue_bytes，形状不全由全量
        # 校验判非法）；均含 queue_bytes 按 link-wire 系路由（事件可含
        # advance），其余沿用 link-forward。
        ports_doc = config.get("ports")
        if (
            isinstance(ports_doc, list)
            and ports_doc
            and all(
                isinstance(p, dict) and "flow_control" in p
                for p in ports_doc
            )
        ):
            # link-flow-decode 仅接受 {t,port,data} 原始帧（PAUSE 为
            # 其中一种），link/advance 同 link-wire；抽象帧与两种帧形
            # 状混用即非法输入；仅 link/advance 项或空事件亦按本模式
            # 路由。
            for event in events if isinstance(events, list) else ():
                if not isinstance(event, dict):
                    raise InvalidInput("bad log event")
                ekeys = frozenset(event)
                if ekeys not in (
                    FRAME_DECODE_FRAME_KEYS,
                    LINK_WIRE_LINK_EVENT_KEYS,
                    LINK_WIRE_ADVANCE_EVENT_KEYS,
                ):
                    raise InvalidInput("bad log event")
            return "link_flow_decode"
        elif (
            isinstance(ports_doc, list)
            and ports_doc
            and all(
                isinstance(p, dict) and "queue_bytes" in p
                for p in ports_doc
            )
        ):
            # link-wire 与 link-wire-decode 共享 queue_bytes 配置：
            # 帧项含 src（九键抽象帧）按 link-wire，含 data（t/port/
